<script>/* =====================================================================
   SoundForest — ambiance + lecteur audio
   - Lucioles dérivantes (canvas), respect de prefers-reduced-motion
   - Brins lumineux animés de la page d'accueil
   - Lecteur : une instance WaveSurfer par carte, initialisée à la volée
     (peaks pré-calculés -> rendu instantané, audio chargé seulement à la lecture)
   ===================================================================== */

const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ----------------------------------------------------------- LUCIOLES */
function initFireflies() {
    const canvas = document.getElementById('fireflies');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let w, h, flies = [];
    const COLORS = ['124,248,176', '255,197,107', '200,162,255'];
    const COUNT = reduceMotion ? 14 : 46;

    function resize() {
        w = canvas.width = window.innerWidth;
        h = canvas.height = window.innerHeight;
    }
    function spawn() {
        flies = Array.from({ length: COUNT }, () => ({
            x: Math.random() * w,
            y: Math.random() * h,
            r: Math.random() * 1.8 + 0.6,
            c: COLORS[Math.floor(Math.random() * COLORS.length)],
            vx: (Math.random() - 0.5) * 0.18,
            vy: (Math.random() - 0.5) * 0.18,
            ph: Math.random() * Math.PI * 2,
            sp: Math.random() * 0.015 + 0.005,
        }));
    }
    function frame() {
        ctx.clearRect(0, 0, w, h);
        for (const f of flies) {
            f.x += f.vx; f.y += f.vy; f.ph += f.sp;
            if (f.x < -10) f.x = w + 10; if (f.x > w + 10) f.x = -10;
            if (f.y < -10) f.y = h + 10; if (f.y > h + 10) f.y = -10;
            const a = 0.35 + Math.sin(f.ph) * 0.35;
            const g = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.r * 7);
            g.addColorStop(0, `rgba(${f.c},${a})`);
            g.addColorStop(1, `rgba(${f.c},0)`);
            ctx.fillStyle = g;
            ctx.beginPath();
            ctx.arc(f.x, f.y, f.r * 7, 0, Math.PI * 2);
            ctx.fill();
        }
        if (!reduceMotion) requestAnimationFrame(frame);
    }
    resize(); spawn();
    window.addEventListener('resize', () => { resize(); spawn(); });
    frame();
}

/* ------------------------------------------------------ BRINS (accueil) */
function initBlades() {
    const root = document.querySelector('.blades');
    if (!root) return;
    const N = 30;
    for (let i = 0; i < N; i++) {
        const b = document.createElement('span');
        b.className = 'blade';
        const t = i / (N - 1);
        const center = 1 - Math.abs(t - 0.5) * 2;          // taller in the middle
        const h = 28 + center * 55 + Math.random() * 14;
        b.style.setProperty('--h', h + '%');
        b.style.setProperty('--d', (1.6 + Math.random() * 2.2).toFixed(2) + 's');
        b.style.animationDelay = (-Math.random() * 3).toFixed(2) + 's';
        root.appendChild(b);
    }
}

/* ----------------------------------------------------------- LECTEUR */
let activeCard = null;       // currently playing card controller

function initPlayer() {
    if (typeof WaveSurfer === 'undefined') return;
    const cards = document.querySelectorAll('.js-card');
    const controllers = new Map();

    const mount = (card) => {
        if (controllers.has(card)) return controllers.get(card);

        const waveEl  = card.querySelector('.js-wave');
        const audioEl = card.querySelector('.js-audio');
        const playBtn = card.querySelector('.js-play');
        const skel    = card.querySelector('.wave-skeleton');
        const peaksEl = card.querySelector('.js-peaks');
        if (!waveEl || !audioEl) return null;

        let peaks = null;
        try { peaks = JSON.parse(peaksEl.textContent); } catch (e) {}
        const duration = parseFloat(card.dataset.duration) || undefined;
        const big = card.classList.contains('js-card-lg');

        const ws = WaveSurfer.create({
            container: waveEl,
            media: audioEl,
            height: big ? 96 : 54,
            barWidth: 2,
            barGap: 2,
            barRadius: 3,
            barAlign: 'bottom',
            cursorWidth: 0,
            normalize: true,
            waveColor: '#3f6b51',
            progressColor: big ? '#ffc56b' : '#7cf8b0',
            peaks: peaks ? [peaks] : undefined,
            duration: duration,
        });

        if (skel) ws.once('ready', () => skel.remove());
        // peaks render synchronously; remove skeleton on next tick as well
        if (skel) setTimeout(() => skel.remove(), 80);

        ws.on('play',  () => card.classList.add('is-playing'));
        ws.on('pause', () => card.classList.remove('is-playing'));
        ws.on('finish', () => card.classList.remove('is-playing'));
        ws.on('loading', () => card.classList.add('is-loading'));
        ws.on('ready',   () => card.classList.remove('is-loading'));

        const ctrl = { ws, card };
        controllers.set(card, ctrl);
        return ctrl;
    };

    const toggle = (card) => {
        const ctrl = mount(card);
        if (!ctrl) return;
        if (activeCard && activeCard !== ctrl) activeCard.ws.pause();
        if (ctrl.ws.isPlaying()) {
            ctrl.ws.pause();
        } else {
            ctrl.ws.play();
            activeCard = ctrl;
        }
    };

    cards.forEach((card) => {
        const playBtn = card.querySelector('.js-play');
        playBtn?.addEventListener('click', (e) => { e.preventDefault(); toggle(card); });
    });

    // Pré-rendre les waveforms visibles (sans charger l'audio)
    const io = new IntersectionObserver((entries) => {
        entries.forEach((en) => {
            if (en.isIntersecting) { mount(en.target); io.unobserve(en.target); }
        });
    }, { rootMargin: '200px' });
    cards.forEach((c) => io.observe(c));
}

document.addEventListener('DOMContentLoaded', () => {
    initFireflies();
    initBlades();
    initPlayer();
});
</script>
</x-layout-app>
